// Generated by Cypress Author on 2026-10-22
//
// REN 07 · REN 08 (UI) — Plano_de_Testes_QA_MatchWallet.md §7 (docs-test/areas/ren.md).
// Mostra os mesmos números do mesmo lançamento no histórico do admin, no painel e em "Minha
// carteira", sem vazar a outra carteira, e não apresenta retorno de mês antigo como o do mês atual.
// A regra de "mês atual" e de reinício anual do acumulado é do servidor (ver
// `real/rentabilidade-servidor`); aqui só vale o que a tela faz com a resposta.
//
// ATENÇÃO — "REN 08 · Minha carteira" deve FALHAR: `views/carteira/Performance.vue` chama de "Mês"
// o ÚLTIMO item da série (`serie.at(-1)`), qualquer que seja a competência. Em janeiro, com último
// lançamento em dezembro, o cartão mostra o retorno de dezembro como se fosse do mês.
//
// Observação (sem teste): sem lançamento no ano, o servidor devolve acumulado 0 e a tela mostra
// "+0,00 %" — não dá para distinguir ausência de zero. Decisão de produto pendente.

const A = { id: 'cart-a', nome: 'Carteira Alfa', perfilAlvo: 'MODERADO' }
const B = { id: 'cart-b', nome: 'Carteira Beta', perfilAlvo: 'ARROJADO' }

function detalhe(carteira: typeof A) {
  return {
    ...carteira,
    descricao: 'Descrição',
    ativa: true,
    criadoEm: '2026-01-01T00:00:00.000Z',
    versaoAtual: null,
  }
}

const CLIENTE = {
  id: '11111111-1111-4111-8111-111111111111',
  nome: 'Maria Teste',
  email: 'maria@teste.com',
  perfil: 'cliente',
  perfilInvestidor: 'MODERADO',
  carteiraVinculada: A,
}

function historico(carteira: typeof A, serie: Array<Record<string, unknown>>) {
  return {
    carteiraId: carteira.id,
    carteiraNome: carteira.nome,
    serie,
    acumulado: { carteira: 1.5, cdi: 1, ibov: -2 },
  }
}

const MOVIMENTACOES = (carteiraId: string, mesReferencia: string) => ({
  carteiraId,
  mesReferencia,
  movimentacoes: { entradas: [], saidas: [], alteracoes: [], mantidos: [] },
})

describe('Plano QA · Rentabilidade vista pelo cliente', () => {
  beforeEach(() => {
    cy.bloquearApi()
  })

  it('REN 07 · mesmo lançamento no admin, painel e minha carteira → números iguais e nada da outra carteira', () => {
    const serieA = [
      { mesReferencia: '2026-10', rentabilidade: 1.5, cdi: 1, ibov: -2, percentualCdi: 150 },
    ]
    const serieB = [
      { mesReferencia: '2026-10', rentabilidade: 9.99, cdi: 1, ibov: 7.77, percentualCdi: 999 },
    ]

    cy.stubApi('GET', '/carteiras*', { items: [A, B], total: 2, page: 1, pageSize: 100 }, 'listar')
    cy.stubApi('GET', `/carteiras/${A.id}`, detalhe(A), 'detalheA')
    cy.stubApi('GET', `/carteiras/${B.id}`, detalhe(B), 'detalheB')
    cy.stubApi(
      'GET',
      `/carteiras/${A.id}/versoes*`,
      { items: [], total: 0, page: 1, pageSize: 100 },
      'versoesA',
    )
    cy.stubApi('GET', `/carteiras/${A.id}/historico-performance*`, historico(A, serieA), 'histA')
    cy.stubApi('GET', `/carteiras/${B.id}/historico-performance*`, historico(B, serieB), 'histB')
    cy.stubApi(
      'GET',
      `/carteiras/${A.id}/movimentacoes*`,
      MOVIMENTACOES(A.id, '2026-10'),
      'movimentacoes',
    )
    cy.stubApi(
      'GET',
      '/dashboard/investidor',
      {
        usuario: { nome: CLIENTE.nome, perfilInvestidor: 'MODERADO' },
        suitabilityRealizado: true,
        suitabilityVencido: false,
        carteira: { id: A.id, nome: A.nome, totalAtivos: 0, rentabilidadeUltimoMes: 1.5 },
        ultimoRelatorio: null,
        movimentacoesMes: { novasEntradas: 0, saidas: 0 },
      },
      'dashboard',
    )
    cy.stubApi(
      'GET',
      '/minha-carteira/performance',
      {
        carteiraNome: A.nome,
        mesAtual: { competencia: '2026-10', rentabilidade: 1.5, cdi: 1, percentualCdi: 150 },
        acumuladoAno: { rentabilidade: 1.5, cdi: 1 },
        historicoUltimosMeses: [{ mes: '2026-10', rentabilidade: 1.5, cdi: 1 }],
      },
      'performance',
    )
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: [], total: 0, page: 1, pageSize: 1 },
      'relatorios',
    )

    // Admin: histórico da carteira A.
    cy.stubSessao('admin')
    cy.visit(`/admin/carteiras/${A.id}`)
    cy.contains('[role="tab"]', 'Rentabilidade').click()
    cy.wait('@histA')
    cy.get('[data-cy="rentab-linha"]')
      .should('have.length', 1)
      .and('contain.text', '+1,50 %')
      .and('contain.text', '-2,00 %')
      .and('contain.text', '150,0 %')

    // Cliente vinculado a A: painel e minha carteira repetem os números.
    cy.intercept('GET', '**/api/v1/auth/me', CLIENTE).as('me')
    cy.visit('/')
    cy.wait('@performance')
    cy.contains('[data-slot="kpi-card"]', 'Rentabilidade do mês')
      .should('contain.text', '+1,50 %')
      .and('contain.text', 'CDI do mês: +1,00 %')

    cy.visit('/carteira')
    // A série de performance só é buscada quando a aba "Performance" é aberta.
    cy.contains('[role="tab"]', 'Performance').click()
    cy.wait('@histA')
    cy.contains('[data-slot="kpi-card"]', 'Mês')
      .should('contain.text', '+1,50 %')
      .and('contain.text', 'CDI +1,00 %')
      .and('contain.text', 'Ibov -2,00 %')

    // Nada da carteira B (9,99 / 7,77) em nenhuma das duas telas, nem chamada ao histórico dela.
    cy.contains('9,99').should('not.exist')
    cy.contains('7,77').should('not.exist')
    cy.get('@histB.all').should('have.length', 0)
  })

  it('REN 08 · virada de ano sem lançamento no mês atual → painel mostra "sem dado" em vez do retorno de dezembro', () => {
    // Relógio em 15/01/2026: só `Date` congela, os timers do app seguem normais.
    cy.clock(Date.UTC(2026, 0, 15, 12), ['Date'])

    cy.intercept('GET', '**/api/v1/auth/me', CLIENTE).as('me')
    cy.stubApi(
      'GET',
      '/dashboard/investidor',
      {
        usuario: { nome: CLIENTE.nome, perfilInvestidor: 'MODERADO' },
        suitabilityRealizado: true,
        suitabilityVencido: false,
        carteira: { id: A.id, nome: A.nome, totalAtivos: 0, rentabilidadeUltimoMes: 1.5 },
        ultimoRelatorio: null,
        movimentacoesMes: { novasEntradas: 0, saidas: 0 },
      },
      'dashboard',
    )
    // Servidor: janeiro sem lançamento → `mesAtual` nulo; dezembro só aparece no histórico.
    cy.stubApi(
      'GET',
      '/minha-carteira/performance',
      {
        carteiraNome: A.nome,
        mesAtual: null,
        acumuladoAno: { rentabilidade: 0, cdi: 0 },
        historicoUltimosMeses: [{ mes: '2025-12', rentabilidade: 1.5, cdi: 1 }],
      },
      'performance',
    )
    cy.stubApi('GET', `/carteiras/${A.id}`, detalhe(A), 'detalhe')
    cy.stubApi(
      'GET',
      `/carteiras/${A.id}/movimentacoes*`,
      MOVIMENTACOES(A.id, '2025-12'),
      'movimentacoes',
    )
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: [], total: 0, page: 1, pageSize: 1 },
      'relatorios',
    )

    cy.visit('/')
    cy.wait('@performance')
    cy.contains('[data-slot="kpi-card"]', 'Rentabilidade do mês')
      .should('contain.text', '—')
      .and('contain.text', 'Sem dado ainda')
      .and('not.contain.text', '+1,50 %')
    // Sem CDI acumulado no ano não há razão a calcular: traço, nunca 0 % nem Infinity.
    cy.contains('[data-slot="kpi-card"]', '% do CDI no ano')
      .should('contain.text', '—')
      .invoke('text')
      .should('not.match', /Infinity|NaN/)
  })

  it('REN 08 · Minha carteira em janeiro com último lançamento em dezembro → o cartão "Mês" não apresenta dezembro como o mês atual (falha até corrigir)', () => {
    cy.clock(Date.UTC(2026, 0, 15, 12), ['Date'])

    cy.intercept('GET', '**/api/v1/auth/me', CLIENTE).as('me')
    cy.stubApi('GET', `/carteiras/${A.id}`, detalhe(A), 'detalhe')
    cy.stubApi(
      'GET',
      `/carteiras/${A.id}/historico-performance*`,
      historico(A, [
        { mesReferencia: '2025-11', rentabilidade: 0.5, cdi: 1, ibov: 0, percentualCdi: 50 },
        { mesReferencia: '2025-12', rentabilidade: 1.5, cdi: 1, ibov: -2, percentualCdi: 150 },
      ]),
      'historico',
    )
    // A aba "Composição" também busca movimentações e o último relatório ao montar.
    cy.stubApi(
      'GET',
      `/carteiras/${A.id}/movimentacoes*`,
      MOVIMENTACOES(A.id, '2025-12'),
      'movimentacoes',
    )
    cy.stubApi(
      'GET',
      '/relatorios/meus-relatorios*',
      { items: [], total: 0, page: 1, pageSize: 1 },
      'relatorios',
    )

    cy.visit('/carteira')
    // A série de performance só é buscada quando a aba "Performance" é aberta.
    cy.contains('[role="tab"]', 'Performance').click()
    cy.wait('@historico')

    // Ou mostra "sem dado" para janeiro, ou rotula a competência (dez); nunca o valor solto.
    cy.contains('[data-slot="kpi-card"]', 'Mês').should(($cartao) => {
      const texto = $cartao.text()
      if (texto.includes('+1,50 %')) {
        expect(texto, 'o retorno de dezembro precisa vir rotulado com a competência').to.match(
          /dez/i,
        )
      }
    })
  })
})

export {}
